from collections import deque
zeros={(r,c) for r in range(H) for c in range(W) if inp[r][c]==0}
stay={(r,c) for r in range(H) for c in range(W) if inp[r][c]==0 and out[r][c]==0}
def fill(moves):
    seen={(r,c) for r in range(H) for c in range(W) if (r in(0,H-1) or c in(0,W-1)) and (r,c) in zeros}
    q=deque(seen)
    while q:
        r,c=q.popleft()
        for dr,dc in moves:
            n=(r+dr,c+dc)
            if n in zeros and n not in seen: seen.add(n); q.append(n)
    return seen
