def dilate(cells):
    s=set()
    for r,c in cells:
        for dr in(-1,0,1):
            for dc in(-1,0,1): s.add((r+dr,c+dc))
    return s
def flood_from_border(walls, moves):
    bg={(r,c) for r in range(H) for c in range(W) if (r,c) not in walls}
    seen={(r,c) for r in range(H) for c in range(W) if (r in(0,H-1) or c in(0,W-1)) and (r,c) in bg}
    q=deque(seen)
    while q:
        r,c=q.popleft()
        for dr,dc in moves:
            n=(r+dr,c+dc)
            if n in bg and n not in seen: seen.add(n); q.append(n)
    return seen
