def bet(r,c,dr,dc):
    a=b=False
    rr,cc=r+dr,c+dc
    while 0<=rr<H and 0<=cc<W:
        if inp[rr][cc]==5: a=True; break
        rr+=dr; cc+=dc
    rr,cc=r-dr,c-dc
    while 0<=rr<H and 0<=cc<W:
        if inp[rr][cc]==5: b=True; break
        rr-=dr; cc-=dc
    return a and b
